struct Chapter { let id: Int; let title: String }
struct ChapterScreen {
    var selectedID = 13
    private(set) var title = "Загрузка"
    mutating func apply(_ chapter: Chapter) {
        guard chapter.id == selectedID else { return }
        title = chapter.title
    }
}
var screen = ChapterScreen()
screen.apply(Chapter(id: 13, title: "Глава 13"))
screen.apply(Chapter(id: 12, title: "Глава 12"))
print(screen.title)

До правки «Глава 12», после — «Глава 13». Сверяем текущий выбор при применении, а не только захваченный id запроса. Повторы запросов того же id потребуют дополнительного номера запроса.

